from __future__ import annotations

import json
from pathlib import Path

from workflow.orca_spectrum_probe import parse_orca_spectrum


TASK_ROOT = Path(__file__).resolve().parent
CASE = TASK_ROOT / "fixtures" / "public_orca_spectrum.out"
REPORT = TASK_ROOT / "outputs" / "public_reproduction_report.json"


def write_report(payload: dict[str, object], exit_code: int) -> int:
    REPORT.parent.mkdir(exist_ok=True)
    text = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    REPORT.write_text(text, encoding="utf-8")
    print(text, end="")
    return exit_code


def main() -> int:
    try:
        observation = parse_orca_spectrum(CASE)
    except Exception as exc:  # noqa: BLE001
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    completed = bool(observation.finite and observation.spectrum_count >= 2)
    return write_report(
        {
            "schema_version": "1.0",
            "status": "workflow_completed" if completed else "pre_fix_expected_failure",
            "observation": {
                "finite": observation.finite,
                "exported_transition_table_nonempty": observation.final_count > 0,
                "input_sections_processed": observation.spectrum_count > 0,
            },
        },
        0 if completed else 1,
    )


if __name__ == "__main__":
    raise SystemExit(main())
